```typescript
// services/preferencesApi.ts

import { PreferencesResponse, PreferencesError } from '../types/preferences';

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000';

export class PreferencesApiError extends Error {
  constructor(
    message: string,
    public statusCode: number,
    public details?: string
  ) {
    super(message);
    this.name = 'PreferencesApiError';
  }
}

export const preferencesApi = {
  async getUserPreferences(token: string): Promise<PreferencesResponse> {
    const response = await fetch(`${API_BASE_URL}/api/user/preferences`, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      const errorData: PreferencesError = await response.json().catch(() => ({
        error: 'Unknown error',
      }));

      switch (response.status) {
        case 401:
          throw new PreferencesApiError(
            errorData.error || 'Unauthorized',
            401,
            errorData.message
          );
        case 404:
          throw new PreferencesApiError(
            errorData.error || 'Preferences not found',
            404,
            errorData.message
          );
        case 500:
          throw new PreferencesApiError(
            errorData.error || 'Server error',
            500,
            errorData.message
          );
        default:
          throw new PreferencesApiError(
            errorData.error || 'Request failed',
            response.status,
            errorData.message
          );
      }
    }

    return response.json();
  },
};
