## 3. React Hook

```typescript
// hooks/useUserPreferences.ts

import { useState, useEffect, useCallback } from 'react';
import { UserPreferences, PreferencesState } from '../types/preferences';
import { preferencesApi, PreferencesApiError } from '../services/preferencesApi';

interface UseUserPreferencesOptions {
  token: string | null;
  autoFetch?: boolean;
}

export const useUserPreferences = ({ 
  token, 
  autoFetch = true 
}: UseUserPreferencesOptions) => {
  const [state, setState] = useState<PreferencesState>({
    preferences: null,
    loading: false,
    error: null,
  });

  const fetchPreferences = useCallback(async () => {
    if (!token) {
      setState({
        preferences: null,
        loading: false,
        error: 'No authentication token provided',
      });
      return;
    }

    setState((prev) => ({ ...prev, loading: true, error: null }));

    try {
      const response = await preferencesApi.getUserPreferences(token);
      setState({
        preferences: response.data,
        loading: false,
        error: null,
      });
    } catch (error) {
      if (error instanceof PreferencesApiError) {
        setState({
          preferences: null,
          loading: false,
          error: error.details || error.message,
        });
      } else {
        setState({
          preferences: null,
          loading: false,
          error: 'An unexpected error occurred',
        });
      }
    }
  }, [token]);

  useEffect(() => {
    if (autoFetch && token) {
      fetchPreferences();
    }
  }, [autoFetch, token, fetchPreferences]);

  return {
    preferences: state.preferences,
    loading: state.loading,
    error: state.error,
    refetch: fetchPreferences,
  };
};
