// context/PreferencesContext.tsx

import React, { createContext, useContext, ReactNode } from 'react';
import { useUserPreferences } from '../hooks/useUserPreferences';
import { UserPreferences } from '../types/preferences';

interface PreferencesContextType {
  preferences: UserPreferences | null;
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

const PreferencesContext = createContext<PreferencesContextType | undefined>(
  undefined
);

interface PreferencesProviderProps {
  children: ReactNode;
  token: string | null;
}

export const PreferencesProvider: React.FC<PreferencesProviderProps> = ({
  children,
  token,
}) => {
  const { preferences, loading, error, refetch } = useUserPreferences({ 
    token, 
    autoFetch: true 
  });

  return (
    <PreferencesContext.Provider value={{ preferences, loading, error, refetch }}>
      {children}
    </PreferencesContext.Provider>
  );
};

export const usePreferencesContext = (): PreferencesContextType => {
  const context = useContext(PreferencesContext);
  if (context === undefined) {
    throw new Error('usePreferencesContext must be used within PreferencesProvider');
  }
  return context;
};
