    (preferencesApi.getUserPreferences as jest.Mock).mockResolvedValueOnce({
      success: true,
      data: mockPreferences,
    });

    const { result } = renderHook(() =>
      useUserPreferences({ token: mockToken, autoFetch: true })
    );

    expect(result.current.loading).toBe(true);

    await waitFor(() => {
      expect(result.current.loading).toBe(false);
    });

    expect(result.current.preferences).toEqual(mockPreferences);
    expect(result.current.error).toBeNull();
  });

  it('should handle errors correctly', async () => {
    const mockError = new Error('Failed to fetch');
    (preferencesApi.getUserPreferences as jest.Mock).mockRejectedValueOnce(
      mockError
    );

    const { result } = renderHook(() =>
      useUserPreferences({ token: mockToken, autoFetch: true })
    );

    await waitFor(() => {
      expect(result.current.loading).toBe(false);
    });

    expect(result.current.preferences).toBeNull();
    expect(result.current.error).toBe('An unexpected error occurred');
  });

  it('should not fetch when token is null', async () => {
    const { result } = renderHook(() =>
      useUserPreferences({ token: null, autoFetch: true })
    );

    expect(result.current.loading).toBe(false);
    expect(result.current.error).toBe('No authentication token provided');
    expect(preferencesApi.getUserPreferences).not.toHaveBeenCalled();
  });

  it('should allow manual refetch', async () => {
    (preferencesApi.getUserPreferences as jest.Mock).mockResolvedValue({
      success: true,
      data: mockPreferences,
    });

    const { result } = renderHook(() =>
      useUserPreferences({ token: mockToken, autoFetch: false })
    );

    expect(result.current.preferences).toBeNull();

    await result.current.refetch();

    await waitFor(() => {
      expect(result.current.preferences).toEqual(mockPreferences);
    });
  });
});
